def build_agent(sandbox):
    # Torso: lightweight and stable
    torso = sandbox.add_beam(x=10.0, y=2.0, width=0.5, height=0.5, density=1.0)

    # Legs: placed at the front and back of the torso
    # Each leg is 1.0m long, 0.1m wide, 0.1m high
    front_leg = sandbox.add_beam(x=9.5, y=2.0, width=0.1, height=0.1, length=1.0, angle=0, density=1.0)
    back_leg = sandbox.add_beam(x=10.5, y=2.0, width=0.1, height=0.1, length=1.0, angle=0, density=1.0)

    # Joints: pivot connections between torso and legs
    front_joint = sandbox.add_joint(torso, front_leg, (10.0, 2.0), type='pivot')
    back_joint = sandbox.add_joint(torso, back_leg, (10.0, 2.0), type='pivot')

    # Set friction to maximum allowed value for traction
    sandbox.set_material_properties(front_leg, friction=0.2)
    sandbox.set_material_properties(back_leg, friction=0.2)

    return {"body": torso, "joints": [front_joint, back_joint]}

def agent_action(sandbox, agent_body, step_count):
    joints = _get_joints(agent_body)
    torso = agent_body.get("body") if isinstance(agent_body, dict) else None

    # Maintain forward motion with controlled torque
    if torso is not None and torso.position.x > 28.0:
        rotation_speed = 0.0
    else:
        rotation_speed = -2.0  # Reduced speed to stay within joint limits

    # Apply motor torque to legs
    for j in joints:
        sandbox.set_motor(j, rotation_speed, max_torque=100.0)

